(()=>{function facturaRepository(mS,facturaMapper){let url="Factura/";return{getAll:function(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query)).then(response=>response).catch(error=>{let errorResponse={status:error.status,message:"Error al leer los datos de la factura"};return Promise.reject(errorResponse)})},create:function(data){let params=facturaMapper.mapToComprobante(data);return mS.getData("post",url,params,!0)},update:function(id,data){let params=facturaMapper.mapToComprobante(data);return mS.getData("put",url+"/"+id,params,!0)},delete:function(id){return mS.getData("delete",url+"/"+id,!0)},getById:function(id){}}}function facturaService(mS,validationsUtils,facturaRepository){return{getAll:query=>facturaRepository.getAll(query).catch(error=>{throw console.error("Error al obtener datos de la factura -> service:",errorResponse),new Error(errorResponse.message)}),create:data=>facturaRepository.create(data).catch(error=>{throw console.error("Error al crear una factura -> service:",errorResponse),new Error(errorResponse.message)})}}function facturaCtrl($scope,facturaService,modalService){$scope.data={},$scope.invoices=[],$scope.dataSearch={},$scope.getInvoices=()=>{try{showLoader(),$scope.invoices=[],facturaService.getAll($scope.query).then(invoices=>{$scope.invoices=invoices}).catch(error=>{hideLoader(),console.log(error)})}catch(error){hideLoader()}},$scope.openModalFiltro=()=>{}}app.factory("facturaMapper",(function(){return{mapToComprobante:function(data){return{idCliente:data.idCliente,fechaEmision:data.fechaEmision}},mapFromComprobante:function(data){return{}}}})),app.factory("facturaRepository",facturaRepository),facturaRepository.$inject=["mainService","facturaMapper"],app.factory("validationsUtils",(function(){return{isNumber:function(value){return!isNaN(value)&&isFinite(value)}}})),app.factory("facturaService",facturaService),facturaService.$inject=["mainService","validationsUtils","facturaRepository"],app.controller("facturaCtrl",facturaCtrl),facturaCtrl.$inject=["$scope","facturaService","modalService"]})(window.angular);